result:
.search-box{
	display: flex
	align-items: center
	justify-content: center
	width: 100%
	height: 48px
	padding: 9px 15px
	cursor: pointer;
	.search{
		width: 100%
		.text{
			width: 46px;
			height: 26px;
			border-radius: 13px;
			text-align: center;
			line-height: 26px;
			color: #fff;
			font-size: 11px;
		}
		.text2{
			font-size: 15px;
			margin-left: 10px;
		}
		.hotWords{
			color: rgba(255,255,255,0.8);
		}
	}
	.title{
	    margin-right: 15px;
	    font-size: 15px;
		color: #333;
	}
	.map{
	    color: #fff;
	    font-size: 15px
	    margin-right: 11px
	    .iconfont{
	        font-size: 16px;
	    }
	    .iconxiayi{
	        font-size: 12px;
	    }
	}
	img{
		width: 76px
		height: 30px
		margin-right: 11px
	}
	.box{
		flex: 1
		height: 30px
		line-height: 30px
		color: #ccc
		font-size: 14px
		padding-left: 16px
		background: #fff
		border-radius:15px;

		&.on{
			text-align: center
		}
		.iconfont{
		    margin-right: 5px
		    margin-top: -3px;
		    display: inline-block;
		    vertical-align: middle;
		}
	}
}
